import json
with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)
# Search for exchange rate related content
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'exchange' in k.lower() or 'pound' in k.lower() or 'sterling' in k.lower() or 'gbp' in k.lower() or 'rate' in k.lower():
                print(f'{path}.{k}: {str(v)[:200]}')
            search(v, f'{path}.{k}')
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            search(item, f'{path}[{i}]')

search(data)
