import json

with open('/app/resources/treasury_bulletin_1963_12.json', 'r') as f:
    data = json.load(f)

# Find elements that might contain exchange rate data
def find_in_elements(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            new_path = f'{path}.{k}'
            if isinstance(v, str) and ('exchange' in v.lower() or 'pound' in v.lower() or 'sterling' in v.lower()):
                print(f'Found at {new_path}: {v[:300]}')
            find_in_elements(v, new_path)
    elif isinstance(obj, list):
        for i, item in enumerate(obj):
            find_in_elements(item, f'{path}[{i}]')

find_in_elements(data)
